-- =========================================================
-- StudentDB_Realistic.sql
-- Realistic Indian Student Database for MySQL Workbench
-- 1000 Students | 1000 Courses | 1000 Marks records
-- =========================================================

DROP DATABASE IF EXISTS StudentDB;
CREATE DATABASE StudentDB;
USE StudentDB;

-- ---------------------------------------------------------
-- Table: Students
-- ---------------------------------------------------------
CREATE TABLE Students (
    student_id      INT AUTO_INCREMENT PRIMARY KEY,
    first_name      VARCHAR(50) NOT NULL,
    last_name       VARCHAR(50) NOT NULL,
    gender          ENUM('Male','Female') NOT NULL,
    date_of_birth   DATE NOT NULL,
    email           VARCHAR(100) NOT NULL UNIQUE,
    mobile_number   VARCHAR(15) NOT NULL UNIQUE,
    city            VARCHAR(50) NOT NULL,
    state           VARCHAR(50) NOT NULL,
    admission_date  DATE NOT NULL,
    CONSTRAINT chk_mobile_length CHECK (CHAR_LENGTH(mobile_number) = 10)
);


-- ---------------------------------------------------------
-- Table: Courses
-- ---------------------------------------------------------
CREATE TABLE Courses (
    course_id       INT AUTO_INCREMENT PRIMARY KEY,
    course_name     VARCHAR(100) NOT NULL UNIQUE,
    level           ENUM('Beginner','Intermediate','Advanced') NOT NULL,
    duration_months INT NOT NULL,
    instructor      VARCHAR(100) NOT NULL,
    credits         INT NOT NULL,
    CONSTRAINT chk_duration CHECK (duration_months > 0),
    CONSTRAINT chk_credits CHECK (credits > 0)
);


-- ---------------------------------------------------------
-- Table: Marks
-- ---------------------------------------------------------
CREATE TABLE Marks (
    mark_id     INT AUTO_INCREMENT PRIMARY KEY,
    student_id  INT NOT NULL,
    course_id   INT NOT NULL,
    marks       INT NOT NULL,
    grade       VARCHAR(2) NOT NULL,
    semester    INT NOT NULL,
    exam_date   DATE NOT NULL,
    result      ENUM('Pass','Fail') NOT NULL,
    CONSTRAINT fk_marks_student FOREIGN KEY (student_id) REFERENCES Students(student_id)
        ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_marks_course FOREIGN KEY (course_id) REFERENCES Courses(course_id)
        ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT chk_marks_range CHECK (marks BETWEEN 35 AND 100),
    CONSTRAINT chk_semester_range CHECK (semester BETWEEN 1 AND 8)
);


-- ---------------------------------------------------------
-- Helpful indexes
-- ---------------------------------------------------------
CREATE INDEX idx_students_city ON Students(city);
CREATE INDEX idx_students_state ON Students(state);
CREATE INDEX idx_courses_level ON Courses(level);
CREATE INDEX idx_marks_student ON Marks(student_id);
CREATE INDEX idx_marks_course ON Marks(course_id);

-- =========================================================
-- End of StudentDB_Realistic.sql
-- =========================================================



